#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int compare_i64(const void *a, const void *b) {
    long long ia = *(const long long *)a;
    long long ib = *(const long long *)b;
    if (ia < ib) return -1;
    if (ia > ib) return 1;
    return 0;
}

long long *sortPosNeg(const long long *arr, size_t len, size_t *out_len) {
    if (len == 0) {
        *out_len = 0;
        long long *result = malloc(sizeof(long long));
        if (!result) return NULL;
        return result;
    }

    long long *positives = malloc(len * sizeof(long long));
    long long *negatives = malloc(len * sizeof(long long));
    if (!positives || !negatives) {
        free(positives);
        free(negatives);
        *out_len = 0;
        return NULL;
    }

    size_t pos_count = 0;
    size_t neg_count = 0;

    for (size_t i = 0; i < len; i++) {
        if (arr[i] >= 0) {
            positives[pos_count++] = arr[i];
        } else {
            negatives[neg_count++] = arr[i];
        }
    }

    qsort(positives, pos_count, sizeof(long long), compare_i64);
    qsort(negatives, neg_count, sizeof(long long), compare_i64);

    long long *result = malloc(len * sizeof(long long));
    if (!result) {
        free(positives);
        free(negatives);
        *out_len = 0;
        return NULL;
    }

    size_t idx = 0;
    for (size_t i = 0; i < pos_count; i++) {
        result[idx++] = positives[i];
    }
    for (size_t i = 0; i < neg_count; i++) {
        result[idx++] = negatives[i];
    }

    free(positives);
    free(negatives);
    *out_len = len;
    return result;
}

void print_array(const long long *arr, size_t len) {
    printf("[");
    for (size_t i = 0; i < len; i++) {
        printf("%lld", arr[i]);
        if (i < len - 1) printf(", ");
    }
    printf("]");
}

int main(void) {
    struct {
        long long *arr;
        size_t len;
    } test_cases[] = {
        {(long long[]){3, -1, 2, -5, 0, 4, -2}, 7},
        {(long long[]){}, 0},
        {(long long[]){-10, -20, -30}, 3},
        {(long long[]){5, 4, 3, 2, 1}, 5},
        {(long long[]){0, 0, -1, 1, -2, 2}, 6}
    };

    const size_t num_tests = sizeof(test_cases) / sizeof(test_cases[0]);

    for (size_t i = 0; i < num_tests; i++) {
        size_t result_len;
        long long *result = sortPosNeg(test_cases[i].arr, test_cases[i].len, &result_len);

        printf("Test %zu: Input = ", i + 1);
        print_array(test_cases[i].arr, test_cases[i].len);
        printf(", Output = ");
        print_array(result, result_len);
        printf("\n");

        free(result);
    }

    return 0;
}

