import java.util.Arrays;

public class Solution {
    public static int[] sortPosNeg(int[] arr) {
        int[] positives = new int[arr.length];
        int[] negatives = new int[arr.length];
        int first = 0;
        int second = 0;

        for (int num : arr) {
            if (num >= 0) {
                positives[first++] = num;
            } else {
                negatives[second++] = num;
            }
        }

        Arrays.sort(positives, 0, first);
        Arrays.sort(negatives, 0, second);

        int[] result = new int[arr.length];
        System.arraycopy(positives, 0, result, 0, first);
        System.arraycopy(negatives, 0, result, first, second);

        return result;
    }

    public static void main(String[] args) {
        // Test case 1: Mixed positive, negative, and zero
        int[] arr1 = {3, -1, 0, -5, 2, -2, 4};
        System.out.println(Arrays.toString(sortPosNeg(arr1)));

        // Test case 2: All positives including zeros
        int[] arr2 = {5, 0, 3, 1, 0, 4};
        System.out.println(Arrays.toString(sortPosNeg(arr2)));

        // Test case 3: All negatives
        int[] arr3 = {-7, -2, -9, -1, -3};
        System.out.println(Arrays.toString(sortPosNeg(arr3)));

        // Test case 4: Empty array
        int[] arr4 = {};
        System.out.println(Arrays.toString(sortPosNeg(arr4)));

        // Test case 5: Single element boundary
        int[] arr5 = {-1};
        System.out.println(Arrays.toString(sortPosNeg(arr5)));
    }
}
